package tui

import (
	"strings"
	"unicode"

	"github.com/charmbracelet/x/ansi"
)

// terminalText treats content as data. Only styles generated by the renderer
// may reach the terminal; provider/file text cannot set titles or the clipboard.
func terminalText(value string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case r == '\n':
			return r
		case r == '\t':
			return ' '
		case unicode.IsControl(r), r >= 0x202a && r <= 0x202e, r >= 0x2066 && r <= 0x2069:
			return -1
		default:
			return r
		}
	}, ansi.Strip(value))
}

// boundedScreen preserves terminal cells and line geometry, including narrow
// Unicode and combining characters. Borders are included in the caller's budget.
func boundedScreen(value string, width, height int) string {
	if width <= 0 || height <= 0 {
		return ""
	}
	lines := strings.Split(value, "\n")
	if len(lines) > height {
		lines = lines[:height]
	}
	for i := range lines {
		lines[i] = ansi.Truncate(lines[i], width, "")
	}
	return strings.Join(lines, "\n")
}
